func Or(predicates ...predicate.BundleLedgerTransactions) predicate.BundleLedgerTransactions {
	return predicate.BundleLedgerTransactions(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.BundleLedgerTransactions) predicate.BundleLedgerTransactions {
	return predicate.BundleLedgerTransactions(sql.NotPredicates(p))
}
